add_filter( 'woocommerce_product_export_product_query_args', 'perfectpixel_csv_export_by_tag' );

function perfectpixel_csv_export_by_tag( $args ) {
	$tags = array_filter( array_map( 'sanitize_title', explode( ',', '{{export_tag_slugs}}' ) ) );
	if ( $tags ) {
		$args['tag'] = $tags;
	}
	return $args;
}
